begin;
create table public.tax_organizations(id uuid primary key default gen_random_uuid(),legal_name text not null,tax_registration_number text not null,branch_code text not null,address jsonb not null default '{}',activity_code text,environment text not null default 'SANDBOX' check(environment in('SANDBOX','PRODUCTION')),integration_enabled boolean not null default false,created_at timestamptz not null default now(),created_by uuid references auth.users(id),updated_at timestamptz not null default now(),updated_by uuid references auth.users(id),unique(tax_registration_number,branch_code));
create table public.tax_code_mappings(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.tax_organizations(id),source_type text not null check(source_type in('SERVICE','ITEM','ACCOUNT')),source_code text not null,eta_item_type text not null check(eta_item_type in('EGS','GS1')),eta_item_code text not null,tax_type text not null,tax_subtype text not null,rate numeric(7,4) not null default 0 check(rate>=0),active boolean not null default true,created_at timestamptz not null default now(),created_by uuid references auth.users(id),updated_at timestamptz not null default now(),updated_by uuid references auth.users(id),unique(organization_id,source_type,source_code));
create table public.tax_documents(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.tax_organizations(id),document_number text not null,document_type text not null check(document_type in('INVOICE','RECEIPT','CREDIT_NOTE','DEBIT_NOTE')),source_table text,source_id uuid,related_document_id uuid references public.tax_documents(id),issue_at timestamptz not null,total_piasters bigint not null check(total_piasters>=0),payload jsonb not null,status text not null default 'DRAFT' check(status in('DRAFT','READY','SUBMITTED','ACCEPTED','REJECTED','CANCELLED')),eta_uuid text,response_payload jsonb,validation_errors jsonb not null default '[]',attempt_count integer not null default 0,last_attempt_at timestamptz,created_at timestamptz not null default now(),created_by uuid references auth.users(id),updated_at timestamptz not null default now(),updated_by uuid references auth.users(id),unique(organization_id,document_number),unique(source_table,source_id,document_type));
create table public.tax_submission_attempts(id bigint generated always as identity primary key,document_id uuid not null references public.tax_documents(id),adapter text not null check(adapter in('SANDBOX','ETA')),request_hash text not null,response_status integer,response_body jsonb,error_message text,attempted_at timestamptz not null default now(),attempted_by uuid references auth.users(id));
create table public.tax_reconciliations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.tax_organizations(id),period_from date not null,period_to date not null,status text not null default 'DRAFT' check(status in('DRAFT','COMPLETED','REVIEW_REQUIRED')),system_count integer not null default 0,accepted_count integer not null default 0,rejected_count integer not null default 0,variance_count integer not null default 0,details jsonb not null default '{}',created_at timestamptz not null default now(),created_by uuid references auth.users(id),completed_at timestamptz,completed_by uuid references auth.users(id),check(period_to>=period_from));
do $$declare t text;begin foreach t in array array['tax_organizations','tax_code_mappings','tax_documents','tax_submission_attempts','tax_reconciliations'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);execute format('create policy %I on public.%I for select to authenticated using(public.current_finance_role() in(''OWNER'',''FINANCE_MANAGER'',''ACCOUNTANT'',''AUDITOR''))',t||'_read',t);end loop;end$$;
grant insert,update on public.tax_organizations,public.tax_code_mappings,public.tax_documents,public.tax_reconciliations to authenticated;
create policy tax_org_write on public.tax_organizations for all to authenticated using(public.current_finance_role()='OWNER') with check(public.current_finance_role()='OWNER' and updated_by=(select auth.uid()));
create policy tax_mapping_write on public.tax_code_mappings for all to authenticated using(public.current_finance_role() in('OWNER','FINANCE_MANAGER')) with check(public.current_finance_role() in('OWNER','FINANCE_MANAGER') and updated_by=(select auth.uid()));
create policy tax_documents_insert on public.tax_documents for insert to authenticated with check(public.current_finance_role() in('OWNER','FINANCE_MANAGER','ACCOUNTANT') and status='DRAFT' and created_by=(select auth.uid()));
create policy tax_documents_update on public.tax_documents for update to authenticated using(public.current_finance_role() in('OWNER','FINANCE_MANAGER','ACCOUNTANT') and status in('DRAFT','READY','REJECTED')) with check(public.current_finance_role() in('OWNER','FINANCE_MANAGER','ACCOUNTANT') and status in('DRAFT','READY','REJECTED') and updated_by=(select auth.uid()));
create policy tax_reconciliation_write on public.tax_reconciliations for all to authenticated using(public.current_finance_role() in('OWNER','FINANCE_MANAGER')) with check(public.current_finance_role() in('OWNER','FINANCE_MANAGER'));
create index tax_documents_queue_idx on public.tax_documents(status,issue_at);create index tax_attempts_document_idx on public.tax_submission_attempts(document_id,attempted_at desc);

create or replace function public.tax_mark_ready(p_document uuid) returns void language plpgsql security definer set search_path='public','private','pg_temp' as $$declare d public.tax_documents%rowtype;begin if public.current_finance_role() not in('OWNER','FINANCE_MANAGER','ACCOUNTANT') then raise exception 'Not authorized';end if;select * into d from public.tax_documents where id=p_document for update;if d.status not in('DRAFT','REJECTED') then raise exception 'Document cannot be marked READY';end if;if jsonb_typeof(d.payload)<>'object' or d.total_piasters<=0 then raise exception 'Document payload or total is invalid';end if;if not exists(select 1 from public.tax_organizations o where o.id=d.organization_id and o.integration_enabled) then raise exception 'Tax integration is not enabled';end if;update public.tax_documents set status='READY',validation_errors='[]',updated_at=now(),updated_by=auth.uid() where id=d.id;insert into public.audit_events(table_name,record_id,action,old_data,new_data,changed_by)values('tax_documents',d.id::text,'MARK_READY',jsonb_build_object('status',d.status),jsonb_build_object('status','READY'),auth.uid());end$$;
create or replace function public.tax_process_sandbox(p_document uuid) returns jsonb language plpgsql security definer set search_path='public','private','pg_temp' as $$declare d public.tax_documents%rowtype;o public.tax_organizations%rowtype;h text;resp jsonb;begin if public.current_finance_role() not in('OWNER','FINANCE_MANAGER') then raise exception 'Not authorized';end if;select * into d from public.tax_documents where id=p_document for update;select * into o from public.tax_organizations where id=d.organization_id;if d.status<>'READY' then raise exception 'Document is not READY';end if;if o.environment<>'SANDBOX' then raise exception 'Sandbox adapter cannot process Production configuration';end if;h:=encode(digest(d.payload::text,'sha256'),'hex');resp:=jsonb_build_object('adapter','SANDBOX','accepted',true,'simulation',true,'request_hash',h);insert into public.tax_submission_attempts(document_id,adapter,request_hash,response_status,response_body,attempted_by)values(d.id,'SANDBOX',h,200,resp,auth.uid());update public.tax_documents set status='ACCEPTED',eta_uuid='SANDBOX-'||d.id,response_payload=resp,attempt_count=attempt_count+1,last_attempt_at=now(),updated_at=now(),updated_by=auth.uid() where id=d.id;insert into public.audit_events(table_name,record_id,action,old_data,new_data,changed_by)values('tax_documents',d.id::text,'SANDBOX_ACCEPT',jsonb_build_object('status',d.status),resp,auth.uid());return resp;end$$;
revoke all on function public.tax_mark_ready(uuid),public.tax_process_sandbox(uuid) from public,anon;grant execute on function public.tax_mark_ready(uuid),public.tax_process_sandbox(uuid) to authenticated;
comment on function public.tax_process_sandbox(uuid) is 'Simulation only. It never contacts ETA and refuses PRODUCTION configuration.';
commit;
